import{_ as t,o,c as n,ae as a}from"./chunks/framework.BvHJbMD4.js";const g=JSON.parse('{"title":"Part 4: The Political Love Story","description":"","frontmatter":{},"headers":[],"relativePath":"en/drehbuch/teil-4-die-politische-liebesgeschichte.md","filePath":"en/drehbuch/teil-4-die-politische-liebesgeschichte.md"}'),i={name:"en/drehbuch/teil-4-die-politische-liebesgeschichte.md"};function s(r,e,h,l,c,u){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="part-4-the-political-love-story" tabindex="-1">Part 4: The Political Love Story <a class="header-anchor" href="#part-4-the-political-love-story" aria-label="Permalink to &quot;Part 4: The Political Love Story&quot;">​</a></h1><p><strong>Working Title:</strong> <em>The Rain of Gold</em></p><p><strong>Cast:</strong> Birgit Minichmayr (Heidi Horten), Oliver Masucci (The Secretary General / PR Consultant), August Diehl (The Investigative Reporter / A satirical Member of Parliament).</p><hr><h2 id="scene-1-the-back-room-of-splendor" tabindex="-1">Scene 1: The Back Room of Splendor <a class="header-anchor" href="#scene-1-the-back-room-of-splendor" aria-label="Permalink to &quot;Scene 1: The Back Room of Splendor&quot;">​</a></h2><p><strong>Location:</strong> A gilded separate booth in a Viennese noble café. <strong>Time:</strong> Election year 2017.</p><p>Heidi (Birgit Minichmayr) sits relaxed in a velvet armchair. In front of her lies a checkbook, enthroned like a relic on the table. The Secretary General (Oliver Masucci) leans forward reverently.</p><p><strong>SECRETARY GENERAL</strong> We need... stability, Madame. And stability comes at a price these days. The posters, the online ads... the consultants...</p><p><strong>HEIDI</strong> (smiling) I love stability. Helmut used to say: &quot;Money is the glue that holds society together.&quot; But if you use too much glue, you can&#39;t see the seams anymore.</p><hr><h2 id="scene-2-the-donation-splitting-sketch" tabindex="-1">Scene 2: The &quot;Donation Splitting&quot; Sketch <a class="header-anchor" href="#scene-2-the-donation-splitting-sketch" aria-label="Permalink to &quot;Scene 2: The &quot;Donation Splitting&quot; Sketch&quot;">​</a></h2><p><strong>Location:</strong> An office full of shredders and calculators. <strong>Time:</strong> Late at night.</p><p>Three consultants in tailored suits (Masucci, Diehl, Minichmayr in multiple roles) sit around a mountain of 500-euro bills. They have a template in front of them.</p><p><strong>CONSULTANT 1 (Masucci)</strong> Here we have a total of 931,000 euros from Madame. Almost a million! A magnificent chunk. But all at once... it&#39;s indigestible for the Court of Audit.</p><p><strong>CONSULTANT 2 (Diehl)</strong> We need the scalpel. We&#39;ll cut it into exactly 49,000-euro morsels. Not 50,000! At 50,000, the sirens go off. At 49,000... there is holy silence.</p><p><strong>CONSULTANT 3 (Minichmayr)</strong> It&#39;s like pointillism! 19 times 49,000 euros. Many small dots. When you stand in front of it, you only see a bunch of nice, discrete individual donations. Only when you step far away do you see... the empire.</p><hr><h2 id="scene-3-the-rain-of-gold-in-parliament" tabindex="-1">Scene 3: The Rain of Gold in Parliament <a class="header-anchor" href="#scene-3-the-rain-of-gold-in-parliament" aria-label="Permalink to &quot;Scene 3: The Rain of Gold in Parliament&quot;">​</a></h2><p><strong>Location:</strong> The plenary hall of the Austrian National Council. <strong>Time:</strong> A fictional, surreal debate on transparency.</p><p>A Member of Parliament (August Diehl) gives a passionate speech about the &quot;innocence of the donor.&quot; Suddenly, it begins to rain from the ceiling. But it&#39;s not water; it&#39;s golden confetti coins with Heidi&#39;s likeness. Each coin bears the engraving &quot;49,000.&quot;</p><p><strong>MP</strong> (while catching the coins) See? This is not money! This is... appreciation! This is civic engagement in its purest, minted form! Who are we to bite the hand that splits us so wonderfully?</p><p>The other MPs begin to catch the coins with umbrellas they hold upside down.</p><hr><h2 id="scene-4-the-interview-of-forgetfulness" tabindex="-1">Scene 4: The Interview of Forgetfulness <a class="header-anchor" href="#scene-4-the-interview-of-forgetfulness" aria-label="Permalink to &quot;Scene 4: The Interview of Forgetfulness&quot;">​</a></h2><p><strong>Location:</strong> A yacht in the Mediterranean. <strong>Time:</strong> Present day.</p><p>Heidi is interviewed by an investigative journalist (August Diehl). The journalist looks exhausted; Heidi is radiant.</p><p><strong>JOURNALIST</strong> Frau Horten, critics say you are buying political influence with your donations. 931,000 euros is no small change.</p><p><strong>HEIDI</strong> (laughs bell-like) Buying? That is such a... commercial term. I call it &quot;Enabling.&quot; I enable politicians to focus on the essentials without having to worry about their budget. Isn&#39;t that the epitome of freedom?</p><hr><h2 id="scene-5-the-transparency-gala-–-the-height-of-satire" tabindex="-1">Scene 5: The &quot;Transparency Gala&quot; – The Height of Satire <a class="header-anchor" href="#scene-5-the-transparency-gala-–-the-height-of-satire" aria-label="Permalink to &quot;Scene 5: The &quot;Transparency Gala&quot; – The Height of Satire&quot;">​</a></h2><p><strong>Location:</strong> A magnificent ballroom where &quot;Transparency&quot; is celebrated as a theme. <strong>Time:</strong> A fictional gala event.</p><p>Each guest wears a mask of semi-transparent plastic. The faces are visible, but distorted.</p><p><strong>CHRONICLER (Masucci, Off-voice)</strong> They celebrated openness while they closed the doors. They called it a &quot;new style&quot; while they refined Helmut&#39;s old recipes. Heidi sat in the middle, the sun of her own system. Every 49,000-euro tranche on her necklace corresponded to a small attention to a political section.</p><p>Heidi dances with a minister. She whispers something in his ear. He nods vigorously, as if receiving divine inspiration.</p><hr><h2 id="scene-6-the-court-of-audit-nightmare" tabindex="-1">Scene 6: The &quot;Court of Audit Nightmare&quot; <a class="header-anchor" href="#scene-6-the-court-of-audit-nightmare" aria-label="Permalink to &quot;Scene 6: The &quot;Court of Audit Nightmare&quot;&quot;">​</a></h2><p><strong>Location:</strong> A dark archive where a lonely auditor (Oliver Masucci) tries to trace the donation paths. <strong>Time:</strong> Night.</p><p>The file folders begin to move on their own. Numbers jump off the pages and form patterns on the walls.</p><p><strong>AUDITOR</strong> It&#39;s a labyrinth of silk and gold! You follow a 49,000-euro donation and land at an equestrian event in Carinthia. You follow the equestrian event and land at an art event in Vienna. And in the end... in the end there is always only one name. But the name is legal. It is so legal it hurts.</p><p>He is buried by a mountain of golden &quot;dots.&quot;</p><hr><h2 id="scene-7-the-finale-–-the-eternity-of-capital" tabindex="-1">Scene 7: The Finale – The Eternity of Capital <a class="header-anchor" href="#scene-7-the-finale-–-the-eternity-of-capital" aria-label="Permalink to &quot;Scene 7: The Finale – The Eternity of Capital&quot;">​</a></h2><p><strong>Location:</strong> Heidi&#39;s mausoleum or a modern art gallery. <strong>Time:</strong> In the near future.</p><p>We see a giant canvas. On it is a depiction of Helmut Horten, but the image consists of millions of small euro symbols. Heidi steps in front of it.</p><p><strong>HEIDI</strong> (to the audience) Helmut said that capital never dies. He was right. It only changes its form. Before, it was department stores; today, it&#39;s parliaments. Before, it was &quot;market consolidation&quot;; today, it&#39;s &quot;policy design.&quot; But the pointillism remains the same.</p><p>She presses a button. The image of Helmut transforms into the logo of a political party and then back again.</p><hr><h2 id="scene-8-the-burial-of-silence-and-the-fear-in-linz" tabindex="-1">Scene 8: The Burial of Silence (and the Fear in Linz) <a class="header-anchor" href="#scene-8-the-burial-of-silence-and-the-fear-in-linz" aria-label="Permalink to &quot;Scene 8: The Burial of Silence (and the Fear in Linz)&quot;">​</a></h2><p><strong>Location:</strong> An exclusive funeral service on Lake Wörthersee. White marble, black ribbons, champagne coolers. <strong>Time:</strong> June 2022 (flashback) / Cut to February 2026 (present).</p><p>A fictional ÖVP parliamentary group leader &quot;August W.&quot; (August Diehl) stands at the buffet. He looks nervous, constantly on the phone. In the background, we see the magnificent photo of the deceased Heidi.</p><p><strong>AUGUST W.</strong> (into the phone, whispering) Yes, I know the appointment in Linz is in March! But I can&#39;t talk about the tax office in Braunau now. We are currently burying the mother of all donation lists! If this legacy isn&#39;t... &quot;structured,&quot; then Braunau is our smallest problem.</p><p><strong>AUDITOR / CONSULTANT (Masucci)</strong> (steps in) August, relax. Heidi left us 931,000 reasons why we are invincible. Even though she&#39;s gone now... the dots continue to work.</p><p><strong>AUGUST W.</strong> (bitterly) The dots! In Linz, they call it &quot;abuse of office.&quot; I call it &quot;regional personnel planning.&quot; Heidi showed us how to make millions invisible, and I can&#39;t even manage to place a mayor in Braunau without the WKStA taking notes? This is the end of aesthetics, I tell you!</p><hr><h2 id="scene-9-the-ghostly-hour-of-the-balance-sheets" tabindex="-1">Scene 9: The Ghostly Hour of the Balance Sheets <a class="header-anchor" href="#scene-9-the-ghostly-hour-of-the-balance-sheets" aria-label="Permalink to &quot;Scene 9: The Ghostly Hour of the Balance Sheets&quot;">​</a></h2><p><strong>Location:</strong> Heidi&#39;s empty bedroom. <strong>Time:</strong> Night.</p><p>August W. slinks through the room. He&#39;s not looking for jewelry, but for more checkbooks. Suddenly, Heidi&#39;s ghost (Birgit Minichmayr) appears in the mirror.</p><p><strong>HEIDI (GHOST)</strong> August... you are so... small-minded. You&#39;re worried about a post in Upper Austria? I&#39;ve repainted entire sections. In gold.</p><p><strong>AUGUST W.</strong> (shivering) Madame, times have changed! The Court of Audit has eyes now! And Thomas Schmid is singing louder than the Vienna Boys&#39; Choir!</p><p><strong>HEIDI (GHOST)</strong> Then sing along, August. But sing in 49,000-euro measures. Then no one understands the lyrics, but everyone loves the melody.</p><hr><h2 id="scene-10-the-last-brushstroke" tabindex="-1">Scene 10: The Last Brushstroke <a class="header-anchor" href="#scene-10-the-last-brushstroke" aria-label="Permalink to &quot;Scene 10: The Last Brushstroke&quot;">​</a></h2><p><strong>Location:</strong> An empty stage. <strong>Time:</strong> Now.</p><p>The three actors (Diehl, Masucci, Minichmayr) step out of their roles. They take off their costumes.</p><p><strong>AUGUST DIEHL</strong> Is it true? <strong>OLIVER MASUCCI</strong> It&#39;s better than true. It&#39;s documented. <strong>BIRGIT MINICHMAYR</strong> It&#39;s a mockumentary. We can tell the truth as long as we claim it&#39;s invented.</p><p>They look together into the camera. In the background, we see the logo of the website: <em>The Horten Mystery</em>.</p><p><strong>FADE OUT.</strong></p>',67)])])}const p=t(i,[["render",s]]);export{g as __pageData,p as default};
